-- =========================================================================
-- SENDUU — Taxonomie catégories/sous-catégories réelle (13 catégories,
-- ~100 sous-catégories). Idempotent via ON CONFLICT (slug) : peut être
-- rejoué sans créer de doublons. "Offres & Promotions" est une catégorie
-- vitrine sans sous-catégorie physique — ses "sous-rubriques" (Flash
-- Deals, Nouveautés...) sont des collections dynamiques pilotées par les
-- flags produit (is_flash_deal, is_new...), pas de fausses catégories.
-- =========================================================================

on conflict (slug) do update set name = excluded.name, sort_order = excluded.sort_order, is_active = true, is_visible = true;

on conflict (slug) do update set name = excluded.name, category_id = excluded.category_id, sort_order = excluded.sort_order, is_active = true, is_visible = true;
